<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Security\KeyRingSecretStorage;
use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use PHPUnit\Framework\TestCase;

#[AllowMockObjectsWithoutExpectations]
final class KeyRingSecretStorageUnitTest extends TestCase
{
    public function test_seal_and_open(): void
    {
        $storage = new KeyRingSecretStorage(['k1' => 'secret-one'], 'k1');

        $sealed = $storage->seal('JBSWY3DPEHPK3PXP', 'ctx#user-1');

        $this->assertStringStartsWith('sealed:k1:', $sealed);
        $this->assertStringNotContainsString('JBSWY3DPEHPK3PXP', $sealed);
        $this->assertNotEquals($sealed, $storage->seal('JBSWY3DPEHPK3PXP', 'ctx#user-1'));
        $this->assertEquals('JBSWY3DPEHPK3PXP', $storage->open($sealed, 'ctx#user-1'));
        $this->assertFalse($storage->needsReseal($sealed));
    }

    public function test_open_with_other_context_fails(): void
    {
        $storage = new KeyRingSecretStorage(['k1' => 'secret-one'], 'k1');
        $sealed = $storage->seal('seed', 'ctx#user-1');

        $this->expectException(InvalidArgumentException::class);
        $storage->open($sealed, 'ctx#user-2');
    }

    public function test_tampered_value_fails(): void
    {
        $storage = new KeyRingSecretStorage(['k1' => 'secret-one'], 'k1');
        $sealed = $storage->seal('seed', 'ctx');
        $tampered = substr($sealed, 0, -2) . ('AA' === substr($sealed, -2) ? 'BB' : 'AA');

        $this->expectException(InvalidArgumentException::class);
        $storage->open($tampered, 'ctx');
    }

    public function test_rotation_keeps_old_values_readable_and_flags_reseal(): void
    {
        $old = new KeyRingSecretStorage(['k1' => 'secret-one'], 'k1');
        $sealed = $old->seal('seed', 'ctx');
        $rotated = new KeyRingSecretStorage(['k2' => 'secret-two', 'k1' => 'secret-one'], 'k2');

        $this->assertEquals('seed', $rotated->open($sealed, 'ctx'));
        $this->assertTrue($rotated->needsReseal($sealed));
        $this->assertStringStartsWith('sealed:k2:', $rotated->seal('seed', 'ctx'));
    }

    public function test_unknown_key_fails(): void
    {
        $sealed = (new KeyRingSecretStorage(['k1' => 'secret-one'], 'k1'))->seal('seed', 'ctx');
        $other = new KeyRingSecretStorage(['k2' => 'secret-two'], 'k2');

        $this->expectException(InvalidArgumentException::class);
        $other->open($sealed, 'ctx');
    }

    public function test_unsealed_values_fail(): void
    {
        $storage = new KeyRingSecretStorage(['k1' => 'secret-one'], 'k1');

        $this->expectException(InvalidArgumentException::class);
        $storage->open('cyphered://abc', 'ctx');
    }

    public function test_reseal_check_on_unsealed_values_fail(): void
    {
        $storage = new KeyRingSecretStorage(['k1' => 'secret-one'], 'k1');

        $this->expectException(InvalidArgumentException::class);
        $storage->needsReseal('plain');
    }

    public function test_current_key_must_be_on_the_ring(): void
    {
        $this->expectException(InvalidArgumentException::class);
        new KeyRingSecretStorage(['k1' => 'secret-one'], 'k2');
    }

    public function test_from_config_with_key_ring(): void
    {
        $config = $this->createMock(AppConfig::class);
        $config->method('get')->willReturnCallback(fn (string $name, mixed $def = null) => match ($name) {
            'security.secrets.keys' => 'k2:c2VjcmV0LXR3bw==, k1:c2VjcmV0LW9uZQ==',
            'security.secrets.current' => 'k2',
            default => $def,
        });

        $storage = KeyRingSecretStorage::fromConfig($config);

        $this->assertStringStartsWith('sealed:k2:', $storage->seal('seed', 'ctx'));
        $this->assertFalse($storage->usesDefaultKey());
    }

    public function test_from_config_without_keys_uses_the_default_one(): void
    {
        $config = $this->createMock(AppConfig::class);
        $config->method('get')->willReturnCallback(fn (string $name, mixed $def = null) => $def);

        $storage = KeyRingSecretStorage::fromConfig($config);

        $this->assertStringStartsWith('sealed:' . KeyRingSecretStorage::DEFAULT_KEY_ID . ':', $storage->seal('seed', 'ctx'));
        $this->assertTrue($storage->usesDefaultKey());
    }
}
